#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

struct Point {
   double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0, 0, 0, 0};

    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 4>> local(static_cast<size_t>(max_threads), {0, 0, 0, 0});

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &lb = local[static_cast<size_t>(tid)];

        #pragma omp for nowait
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Bin mapping:
            // 0: x>=0, y>=0
            // 1: x<0,  y>=0
            // 2: x<0,  y<0
            // 3: x>=0, y<0
            if (x >= 0.0) {
                if (y >= 0.0) ++lb[0];
                else          ++lb[3];
            } else {
                if (y >= 0.0) ++lb[1];
                else          ++lb[2];
            }
        }
    }

    for (const auto &lb : local) {
        bins[0] += lb[0];
        bins[1] += lb[1];
        bins[2] += lb[2];
        bins[3] += lb[3];
    }
}
